-- stochastic-processes implementation for StochasticRK
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.HeunStep(x,dt,drift,diffusion,normalSample)
    Num.Positive(dt,"time step")
    local dW=math.sqrt(dt)*normalSample; local predictor=x+drift(x)*dt+diffusion(x)*dW
    local correctedDrift=0.5*(drift(x)+drift(predictor)); local correctedDiffusion=0.5*(diffusion(x)+diffusion(predictor))
    return x+correctedDrift*dt+correctedDiffusion*dW
end

return Module
